1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: price list, single main items (new customer, first contract) ---
6	  it("quotes a sword for a new customer — base 100 G, +10 % first insurance, +5 G fee = 115 G", () => {
7	    const result = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [
10	        {
11	          op: "quote",
12	          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
13	        },
14	      ],
15	    });
16	
17	    expect(result).toEqual({ results: [{ premium: 115 }] });
18	  });
19	  it.todo("quotes an amulet for a new customer — base 60 G, +10 % first insurance, +5 G fee = 71 G");
20	  it.todo("quotes a staff for a new customer — base 80 G, +10 % first insurance, +5 G fee = 93 G");
21	  it.todo("quotes a potion for a new customer — base 40 G, +10 % first insurance, +5 G fee = 49 G");
22	
23	  // --- Quote: components and building blocks ---
24	  it.todo("quotes a single rune component — base 25 G, +10 % first insurance, +5 G fee = 33 G");
25	  it.todo("quotes a single moonstone component — base 25 G, +10 % first insurance, +5 G fee = 33 G");
26	  it.todo("quotes 3 alike runes as a building block — special base 60 G instead of 75 G, +10 %, +5 G fee = 71 G");
27	  it.todo("quotes 4 alike runes — building block 60 G + single 25 G = 85 G base, +10 %, +5 G fee = 99 G");
28	  it.todo("quotes 3 runes and 3 moonstones as two separate building blocks — base 120 G, +10 %, +5 G fee = 137 G");
29	  it.todo("does not form a building block from 3 unalike components — 2 runes + 1 moonstone = base 75 G, +10 %, +5 G fee = 88 G");
30	
31	  // --- Quote: risk surcharges ---
32	  it.todo("adds a 50 % risk surcharge for a cursed sword — 150 G, +10 %, +5 G fee = 170 G");
33	  it.todo("adds a 30 % risk surcharge for a highly enchanted sword (enchantment 5) — 130 G, +10 %, +5 G fee = 148 G");
34	  it.todo("does not add the enchantment surcharge below level 5 (enchantment 4) — 100 G, +10 %, +5 G fee = 115 G");
35	  it.todo("combines cursed and high enchantment surcharges on one sword — 100 G × 1.8 = 180 G, +10 %, +5 G fee = 203 G");
36	
37	  // --- Quote: customer modifiers ---
38	  it.todo("grants a 20 % loyalty discount for a customer with 2 years — sword 100 G × 0.8 = 80 G, +10 %, +5 G fee = 93 G");
39	  it.todo("does not grant the loyalty discount below 2 years (1 year) — sword 100 G, +10 %, +5 G fee = 115 G");
40	  it.todo("applies a 15 % discount on the second contract instead of the first-insurance surcharge — sword 100 G × 0.85 = 85 G, +5 G fee = 90 G");
41	  it.todo("applies the 15 % discount to the third contract as well — sword 100 G × 0.85 = 85 G, +5 G fee = 90 G");
42	
43	  // --- Quote: rounding and combinations ---
44	  it.todo("rounds the premium up in MHPCO's favor — loyal customer's first cursed potion: 40 × 1.5 × 0.8 × 1.1 = 52.8 → 53, +5 G fee = 58 G");
45	  it.todo("quotes a mixed list of items in one contract — sword + amulet + 3 runes = 100 + 60 + 60 = 220 G, +10 %, +5 G fee = 247 G");
46	
47	  // --- Claims: deductible ---
48	  it.todo("deducts the 100 G deductible from a single damage — 200 G damage on an amulet pays out 100 G");
49	  it.todo("pays out 0 G when the damage does not exceed the deductible — 100 G damage pays out 0 G");
50	  it.todo("applies the deductible once per damage event, not per damaged item — two 200 G damages in one incident pay out 300 G");
51	
52	  // --- Claims: reimbursement rules ---
53	  it.todo("reimburses damage to an item with enchantment ≥ 8 at 50 % — 400 G damage → 200 G, minus 100 G deductible = 100 G");
54	  it.todo("fully reimburses damage to an item made of dragon material — 400 G damage minus 100 G deductible = 300 G");
55	  it.todo("fully reimburses dragon material even when the enchantment is ≥ 8 — 400 G damage minus 100 G deductible = 300 G");
56	
57	  // --- Claims: cap ---
58	  it.todo("reports the remaining cap after a claim — amulet policy cap 1200 G, payout 100 G leaves 1100 G");
59	  it.todo("caps the payout at twice the insurance sum — amulet policy cap 1200 G, 5000 G damage pays out 1200 G and leaves 0 G");
60	  it.todo("carries the remaining cap across successive claims on the same policy — second claim is limited by what the first left");
61	  it.todo("caps against the summed insurance sum of all insured items — sword + amulet policy cap = 3200 G");
62	
63	  // --- Scenario integration ---
64	  it.todo("processes a quote followed by two claims on the same policy, returning one result per step in order");
65	  it.todo("keeps separate caps for two policies of the same customer");
66	});
