export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: { op: string }[];
};

export type StepResult = { premium: number };

export type ScenarioResult = { results: StepResult[] };

export const runScenario = (_scenario: Scenario): ScenarioResult => {
  return { results: [{ premium: 115 }] };
};

